# Lunar Konstruksi - visual refinement + detail page alignment
# Generated for the current main branch structure.
# Run from repository root:
#   powershell -ExecutionPolicy Bypass -File .\Apply_Lunar_Visual_Refinement_v15.ps1

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Write-Utf8NoBom {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][string]$Content
    )

    $directory = Split-Path -Parent $Path
    if ($directory -and -not (Test-Path $directory)) {
        New-Item -ItemType Directory -Force -Path $directory | Out-Null
    }

    $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($Path, $Content, $utf8NoBom)
}

function Replace-Literal {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][string]$Old,
        [Parameter(Mandatory = $true)][string]$New,
        [switch]$Optional
    )

    if (-not (Test-Path $Path)) {
        if ($Optional) {
            Write-Warning "File tidak ditemukan, dilewati: $Path"
            return
        }

        throw "File tidak ditemukan: $Path"
    }

    $content = [System.IO.File]::ReadAllText($Path)

    if (-not $content.Contains($Old)) {
        if ($Optional) {
            Write-Warning "Pattern tidak ditemukan, dilewati pada: $Path"
            return
        }

        throw "Pattern wajib tidak ditemukan pada $Path`nPattern: $Old"
    }

    $content = $content.Replace($Old, $New)
    Write-Utf8NoBom -Path $Path -Content $content
}

$repoRoot = $PSScriptRoot
if (-not (Test-Path (Join-Path $repoRoot "package.json"))) {
    if (Test-Path (Join-Path (Get-Location) "package.json")) {
        $repoRoot = (Get-Location).Path
    }
    else {
        throw "Jalankan script ini dari root repository Lunar Konstruksi (folder yang berisi package.json)."
    }
}

Write-Host ""
Write-Host "=== Lunar Konstruksi / Visual Refinement v15 ===" -ForegroundColor Cyan
Write-Host "Repo: $repoRoot" -ForegroundColor DarkGray
Write-Host ""

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $repoRoot ".lunar-backups\visual-refinement-v15-$timestamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

$filesToBackup = @(
    "components\site\formwork\header.tsx",
    "components\site\formwork\home.tsx",
    "components\site\formwork\service-staggered-carousel.tsx",
    "components\site\formwork\about.tsx",
    "components\site\formwork\projects.tsx",
    "components\site\formwork\services.tsx",
    "components\site\formwork\contact.tsx",
    "components\site\project-detail-page.tsx",
    "components\site\service-detail-page.tsx",
    "app\projects\[slug]\page.tsx",
    "app\services\[slug]\page.tsx",
    "public\lunar-logo-mark.png"
)

foreach ($relativePath in $filesToBackup) {
    $source = Join-Path $repoRoot $relativePath
    if (Test-Path $source) {
        $destination = Join-Path $backupRoot $relativePath
        $destinationDir = Split-Path -Parent $destination
        New-Item -ItemType Directory -Force -Path $destinationDir | Out-Null
        Copy-Item -Force $source $destination
    }
}

Write-Host "[1/7] Menambahkan logo Lunar untuk navbar..." -ForegroundColor Yellow
$logoBase64 = @'

'@
$logoBytes = [Convert]::FromBase64String(($logoBase64 -replace "\s", ""))
$logoTarget = Join-Path $repoRoot "public\lunar-logo-mark.png"
[System.IO.File]::WriteAllBytes($logoTarget, $logoBytes)

Write-Host "[2/7] Mengganti navbar dengan versi yang lebih bersih dan profesional..." -ForegroundColor Yellow
$headerCode = @'
"use client";

import Image from "next/image";
import Link from "next/link";
import { Menu, X } from "lucide-react";
import { usePathname } from "next/navigation";
import { useState } from "react";

import { displayFont } from "./decor";

const links = [
  { href: "/about", label: "Tentang" },
  { href: "/projects", label: "Proyek" },
  { href: "/services", label: "Layanan" },
  { href: "/contact", label: "Kontak" },
];

function isActivePath(pathname: string, href: string) {
  if (href === "/") return pathname === "/";
  return pathname === href || pathname.startsWith(`${href}/`);
}

export function FormworkHeader() {
  const pathname = usePathname();
  const [open, setOpen] = useState(false);

  return (
    <header className="sticky top-0 z-50 border-b border-[#d8d1c6] bg-[#f5f1e8]/95 text-[#182d4d] backdrop-blur-xl">
      <div className="mx-auto flex h-[82px] w-full max-w-[1480px] items-center justify-between gap-5 px-5 sm:px-8 lg:px-10">
        <Link
          href="/"
          className="group flex min-w-0 items-center gap-3"
          onClick={() => setOpen(false)}
          aria-label="Lunar Konstruksi"
        >
          <span className="grid h-11 w-11 shrink-0 place-items-center">
            <Image
              src="/lunar-logo-mark.png"
              alt=""
              width={750}
              height={770}
              priority
              className="h-11 w-11 object-contain transition duration-300 group-hover:scale-[1.04]"
            />
          </span>
          <span className="hidden min-w-0 sm:block">
            <span
              className={`${displayFont} block text-[1.02rem] font-black uppercase leading-none tracking-[0.12em] text-[#14243f]`}
            >
              Lunar
            </span>
            <span className="mt-1 block font-mono text-[8px] font-semibold uppercase tracking-[0.24em] text-[#b58c2f]">
              Konstruksi
            </span>
          </span>
        </Link>

        <nav className="hidden items-center rounded-full border border-[#d8d1c6] bg-white/35 p-1 lg:flex">
          {links.map((item) => {
            const active = isActivePath(pathname, item.href);

            return (
              <Link
                key={item.href}
                href={item.href}
                className={`rounded-full px-4 py-2.5 text-[11px] font-semibold transition ${
                  active
                    ? "bg-[#14243f] text-[#f8f4ec]"
                    : "text-[#526074] hover:bg-[#ebe5db] hover:text-[#14243f]"
                }`}
              >
                {item.label}
              </Link>
            );
          })}
        </nav>

        <div className="hidden items-center gap-3 lg:flex">
          <span className="h-px w-8 bg-[#dcb458]" />
          <Link
            href="/contact"
            className="inline-flex h-11 items-center justify-center rounded-full border border-[#14243f] px-5 text-[10px] font-bold uppercase tracking-[0.12em] text-[#14243f] transition hover:bg-[#14243f] hover:text-[#f8f4ec]"
          >
            Konsultasikan proyek
          </Link>
        </div>

        <button
          type="button"
          onClick={() => setOpen((value) => !value)}
          className="grid h-11 w-11 place-items-center rounded-full border border-[#cfc8bd] bg-[#faf7f0] lg:hidden"
          aria-label={open ? "Tutup navigasi" : "Buka navigasi"}
          aria-expanded={open}
        >
          {open ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
        </button>
      </div>

      {open ? (
        <div className="border-t border-[#d8d1c6] bg-[#f5f1e8] px-5 pb-6 pt-3 sm:px-8 lg:hidden">
          <nav className="mx-auto flex max-w-[1480px] flex-col">
            {links.map((item) => {
              const active = isActivePath(pathname, item.href);

              return (
                <Link
                  key={item.href}
                  href={item.href}
                  onClick={() => setOpen(false)}
                  className={`flex items-center justify-between border-b border-[#ddd5c8] py-4 text-sm font-semibold ${
                    active ? "text-[#b58c2f]" : "text-[#14243f]"
                  }`}
                >
                  <span>{item.label}</span>
                  <span className="font-mono text-[9px] text-[#8b94a0]">
                    {active ? "ACTIVE" : "OPEN"} →
                  </span>
                </Link>
              );
            })}
            <Link
              href="/contact"
              onClick={() => setOpen(false)}
              className="mt-5 inline-flex h-12 items-center justify-center rounded-full bg-[#14243f] px-5 text-[10px] font-bold uppercase tracking-[0.13em] text-[#f8f4ec]"
            >
              Konsultasikan proyek
            </Link>
          </nav>
        </div>
      ) : null}
    </header>
  );
}

